export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"ideas-for-practicing-wise-mind-the-mindfulness-skills-often-require-a-lot-of-pra-477ec9c869d4\",\"title\":\"Ideas for Practicing Wise Mind The mindfulness skills often require a lot of practice. As with any new skill, it is important to first practice when you don\u2019t need the skill. If you practice in easier situations, the skill will become automatic, and you will have the skill when you need it. Practice with your eyes closed and with\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9819],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/02-dbt-mindfulness-mindfulness-handout-3a-ideas-for-practicing-wise-mind-the-mindfulness-ski-d9f3b17c34.json\",\"sha256\":\"d9f3b17c3460dd817936f9be4d3178b726b6a6d1ced86147b141da664d2b467e\",\"domain\":\"dbt\",\"bytes\":9771},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/mindfulness-handout-3a-ideas-for-practicing-wise-mind-the-mindfulness-skills-often-require-a-aeb0a7a343.json\",\"sha256\":\"aeb0a7a343f488ab593d135683ab262ef8fae3e660ef677ef069c4d570f2f4ec\",\"domain\":\"dbt\",\"bytes\":9618}]},\"data\":{\"pages\":[{\"pdf_page\":75,\"book_page\":\"51\",\"text\":\"51\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nMindfulness Handout 3a   (Mindfulness Worksheet 3) (p. 1 of 2)\\nIdeas for Practicing Wise Mind\\nThe mindfulness skills often require a lot of practice. As with any new skill, it is important to first\\npractice when you don\u2019t need the skill. If you practice in easier situations, the skill will become\\nautomatic, and you will have the skill when you need it. Practice with your eyes closed and with\\nyour eyes open.\\n1.\\t \uf071\\tStone flake on the lake. Imagine that you are by a clear blue lake on a beautiful sunny day.\\nThen imagine that you are a small flake of stone, flat and light. Imagine that you have been\\ntossed out onto the lake and are now gently, slowly, floating through the calm, clear blue\\nwater to the lake\u2019s smooth, sandy bottom.\\n\u2022\u2022 Notice what you see, what you feel as you float down, perhaps in slow circles, floating\\ntoward the bottom. As you reach the bottom of the lake, settle your attention there within\\nyourself.\\n\u2022\u2022 Notice the serenity of the lake; become aware of the calmness and quiet deep within.\\n\u2022\u2022 As you reach the center of your self, settle your attention there.\\n2.\\t \uf071\\tWalking down the spiral stairs. Imagine that within you is a spiral staircase, winding down\\nto your very center. Starting at the top walk very slowly down the staircase, going deeper\\nand deeper within yourself.\\n\u2022\u2022 Notice the sensations. Rest by sitting on a step, or turn on lights on the way down if you\\nwish. Do not force yourself further than you want to go. Notice the quiet. As you reach the\\ncenter of your self, settle your attention there\u2014perhaps in your gut or your abdomen.\\n3.\\t \uf071\\tBreathing \u201cWise\u201d in, \u201cMind\u201d out. Breathing in, say to yourself, \u201cWise\u201d; breathing out, say\\n\u201cMind.\u201d\\n\u2022\u2022 Focus your entire attention on the word \u201cwise,\u201d then, focus it again entirely on the word\\n\u201cmind.\u201d\\n\u2022\u2022 Continue until you sense that you have settled into Wise Mind.\\n4.\\t \uf071\\tAsking Wise Mind a question. Breathing in, silently ask Wise Mind a question.\\n\u2022\u2022 Breathing out, listen for the answer.\\n\u2022\u2022 Listen, but do not give yourself the answer. Do not tell yourself the answer; listen for it.\\n\u2022\u2022 Continue asking on each in-breath for some time. If no answer comes, try again another\\ntime.\\n(continued on next page)\"},{\"pdf_page\":76,\"book_page\":\"52\",\"text\":\"52\\nMindfulness Handout 3a   (p. 2 of 2)\\n5.\\t \uf071\\tAsking is this Wise Mind? Breathing in, ask yourself, \u201cIs this (action, thought, plan, etc.)\\nWise Mind?\u201d\\n\u2022\u2022 Breathing out, listen for the answer.\\n\u2022\u2022 Listen, but do not give yourself the answer. Do not tell yourself the answer; listen for it.\\n\u2022\u2022 Continue asking on each in-breath for some time. If no answer comes, try again another\\ntime.\\n6.\\t \uf071\\tAttending to your breath coming in and out, let your attention settle into your center.\\n\u2022\u2022 Breathing in completely, notice and follow the sensations of your breath coming in.\\n\u2022\u2022 Let your attention settle into your center, at the bottom of your breath, at your solar\\nplexus\u2014or\\n\u2022\u2022 Let your attention settle in the center of your forehead, your \u201cthird eye,\u201d at the top of your\\nbreath.\\n\u2022\u2022 Keeping your attention at your center, exhale, breathing normally, maintaining attention.\\n\u2022\u2022 Settle into Wise Mind.\\n7.\\t \uf071\\tExpanding awareness. Breathing in, focus your awareness on your center.\\n\u2022\u2022 Breathing out, stay aware of your center, but expand awareness to the space you are in\\nnow.\\n\u2022\u2022 Continue on in the moment.\\n8.\\t \uf071\\tDropping into the pauses between inhaling and exhaling.\\n\u2022\u2022 Breathing in, notice the pause after inhaling (top of breath).\\n\u2022\u2022 Breathing out, notice the pause after exhaling (bottom of breath).\\n\u2022\u2022 At each pause, let yourself \u201cfall into\u201d the center space within the pause.\\n9.\\t \uf071\\tOther Wise Mind practice ideas:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Mindfulness Handout 3a   (Mindfulness Worksheet 3) (p. 1 of 2)\",\"source_pdf_pages\":[75,76],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/mindfulness/handouts/mindfulness_handout_3a_ideas_for_practicing_wise_mind_the_mindfulness_skills_often_require_a.json\",\"item_number\":\"3a\",\"full_text\":\"Mindfulness Handout 3a   (Mindfulness Worksheet 3) (p. 1 of 2)\\nIdeas for Practicing Wise Mind\\nThe mindfulness skills often require a lot of practice. As with any new skill, it is important to first\\npractice when you don\u2019t need the skill. If you practice in easier situations, the skill will become\\nautomatic, and you will have the skill when you need it. Practice with your eyes closed and with\\nyour eyes open.\\n1.\\t \uf071\\tStone flake on the lake. Imagine that you are by a clear blue lake on a beautiful sunny day.\\nThen imagine that you are a small flake of stone, flat and light. Imagine that you have been\\ntossed out onto the lake and are now gently, slowly, floating through the calm, clear blue\\nwater to the lake\u2019s smooth, sandy bottom.\\n\u2022\u2022 Notice what you see, what you feel as you float down, perhaps in slow circles, floating\\ntoward the bottom. As you reach the bottom of the lake, settle your attention there within\\nyourself.\\n\u2022\u2022 Notice the serenity of the lake; become aware of the calmness and quiet deep within.\\n\u2022\u2022 As you reach the center of your self, settle your attention there.\\n2.\\t \uf071\\tWalking down the spiral stairs. Imagine that within you is a spiral staircase, winding down\\nto your very center. Starting at the top walk very slowly down the staircase, going deeper\\nand deeper within yourself.\\n\u2022\u2022 Notice the sensations. Rest by sitting on a step, or turn on lights on the way down if you\\nwish. Do not force yourself further than you want to go. Notice the quiet. As you reach the\\ncenter of your self, settle your attention there\u2014perhaps in your gut or your abdomen.\\n3.\\t \uf071\\tBreathing \u201cWise\u201d in, \u201cMind\u201d out. Breathing in, say to yourself, \u201cWise\u201d; breathing out, say\\n\u201cMind.\u201d\\n\u2022\u2022 Focus your entire attention on the word \u201cwise,\u201d then, focus it again entirely on the word\\n\u201cmind.\u201d\\n\u2022\u2022 Continue until you sense that you have settled into Wise Mind.\\n4.\\t \uf071\\tAsking Wise Mind a question. Breathing in, silently ask Wise Mind a question.\\n\u2022\u2022 Breathing out, listen for the answer.\\n\u2022\u2022 Listen, but do not give yourself the answer. Do not tell yourself the answer; listen for it.\\n\u2022\u2022 Continue asking on each in-breath for some time. If no answer comes, try again another\\ntime.\\n(continued on next page)\\n\\nMindfulness Handout 3a   (p. 2 of 2)\\n5.\\t \uf071\\tAsking is this Wise Mind? Breathing in, ask yourself, \u201cIs this (action, thought, plan, etc.)\\nWise Mind?\u201d\\n\u2022\u2022 Breathing out, listen for the answer.\\n\u2022\u2022 Listen, but do not give yourself the answer. Do not tell yourself the answer; listen for it.\\n\u2022\u2022 Continue asking on each in-breath for some time. If no answer comes, try again another\\ntime.\\n6.\\t \uf071\\tAttending to your breath coming in and out, let your attention settle into your center.\\n\u2022\u2022 Breathing in completely, notice and follow the sensations of your breath coming in.\\n\u2022\u2022 Let your attention settle into your center, at the bottom of your breath, at your solar\\nplexus\u2014or\\n\u2022\u2022 Let your attention settle in the center of your forehead, your \u201cthird eye,\u201d at the top of your\\nbreath.\\n\u2022\u2022 Keeping your attention at your center, exhale, breathing normally, maintaining attention.\\n\u2022\u2022 Settle into Wise Mind.\\n7.\\t \uf071\\tExpanding awareness. Breathing in, focus your awareness on your center.\\n\u2022\u2022 Breathing out, stay aware of your center, but expand awareness to the space you are in\\nnow.\\n\u2022\u2022 Continue on in the moment.\\n8.\\t \uf071\\tDropping into the pauses between inhaling and exhaling.\\n\u2022\u2022 Breathing in, notice the pause after inhaling (top of breath).\\n\u2022\u2022 Breathing out, notice the pause after exhaling (bottom of breath).\\n\u2022\u2022 At each pause, let yourself \u201cfall into\u201d the center space within the pause.\\n9.\\t \uf071\\tOther Wise Mind practice ideas:\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Mindfulness Worksheet 3\"],\"id\":\"mindfulness_handout_3a\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"51\",\"52\"],\"title\":\"Ideas for Practicing Wise Mind The mindfulness skills often require a lot of practice. As with any new skill, it is important to first practice when you don\u2019t need the skill. If you practice in easier situations, the skill will become automatic, and you will have the skill when you need it. Practice with your eyes closed and with\",\"module_category\":\"Mindfulness Skills\",\"shared_json_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_3a_ideas_for_practicing_wise_mind_the_mindfulness_ski_04fb9dbc.json\",\"module\":\"Mindfulness\",\"keywords\":[\"Ideas\",\"Mind\",\"Practice\",\"Practicing\",\"Wise\",\"automatic\",\"become\",\"closed\",\"easier\",\"eyes\",\"first\",\"have\",\"important\",\"mindfulness\",\"need\",\"often\",\"practice\",\"require\",\"situations\",\"skill\"]}}");
